const { test } = require('node:test')
const assert = require('node:assert')
const Fastify = require('./fastify')

test('unsupported hook name rejects ready', async () => {
  const fastify = Fastify()
  await assert.rejects(fastify.ready(), (err) => {
    assert.strictEqual(err.code, 'FST_ERR_HOOK_NOT_SUPPORTED')
    assert.strictEqual(err.message, 'invalidHook hook not supported!')
    return true
  })
  await fastify.close()
}, fastifySetup())

function fastifySetup () { return undefined }

test('invalid handler rejects ready', async () => {
  const fastify = Fastify()
  fastify.addHook('onRequest', 'not a function')
  await assert.rejects(fastify.ready(), (err) => {
    assert.strictEqual(err.code, 'FST_ERR_HOOK_INVALID_HANDLER')
    assert.strictEqual(err.message, 'onRequest hook should be a function, instead got [object String]')
    return true
  })
  await fastify.close()
})

test('non string hook name rejects ready', async () => {
  const fastify = Fastify()
  fastify.addHook(42, () => {})
  await assert.rejects(fastify.ready(), (err) => {
    assert.strictEqual(err.code, 'FST_ERR_HOOK_INVALID_TYPE')
    return true
  })
  await fastify.close()
})

test('valid hooks still work, incl. children and after() errors', async () => {
  const order = []
  const fastify = Fastify()
  fastify.register(async function (instance) {
    instance.get('/', async () => 'ok')
  })
  fastify.addHook('onRequest', async function () { order.push('onRequest') })
  await fastify.ready()
  const res = await fastify.inject('/')
  assert.strictEqual(res.body, 'ok')
  assert.deepStrictEqual(order, ['onRequest'])
  await fastify.close()
})

test('a previous plugin error is still forwarded', async () => {
  const fastify = Fastify()
  fastify.register(async function () { throw new Error('boom') })
  fastify.addHook('onRequest', async function () {})
  await assert.rejects(fastify.ready(), /boom/)
  await fastify.close()
})

